package io.github.belmantegu.ds.android;

import io.github.belmantegu.ds.core.*;

import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.Path;

import java.util.HashMap;
import java.util.Map;

/**
 * The design system's icons: the official Lucide outlines (https://lucide.dev, ISC license), 24 x 24, as SVG
 * path data in IconData (generated by tools/android/lucide_icons.py), drawn with a stroke of 2 units, round
 * caps and joins, in any colour. Names are Lucide's ("monitor", "chevron-left", ...). The parser knows
 * M L H V C S Q T A Z (absolute and relative; arcs become cubics). Paths are parsed once and cached.
 */
public final class Icons {
    private Icons() {}

    /** Lucide's own stroke width in its 24-unit box. */
    public static final float STROKE = 2f;

    private static final Map<String, Path> CACHE = new HashMap<>();

    /** The icon's path in its 24 x 24 box (an empty path for an unknown name). */
    public static synchronized Path path(String name) {
        Path p = CACHE.get(name);
        if (p == null) {
            p = new Path();
            for (String[] d : IconData.DATA) if (d[0].equals(name)) { parse(d[1], p); break; }
            CACHE.put(name, p);
        }
        return p;
    }

    public static boolean has(String name) {
        for (String[] d : IconData.DATA) if (d[0].equals(name)) return true;
        return false;
    }

    /** Draws the icon in the square at (x, y) of `size` px; `p` is reused (its style and colour are set here). */
    public static void draw(Canvas c, String name, float x, float y, float size, int color, float strokeUnits, Paint p) {
        c.save();
        c.translate(x, y);
        c.scale(size / 24f, size / 24f);
        p.setStyle(Paint.Style.STROKE);
        p.setStrokeWidth(strokeUnits);
        p.setStrokeCap(Paint.Cap.ROUND);
        p.setStrokeJoin(Paint.Join.ROUND);
        p.setColor(color);
        c.drawPath(path(name), p);
        c.restore();
        p.setStyle(Paint.Style.FILL);
        p.setStrokeWidth(0);
    }

    public static void draw(Canvas c, String name, float x, float y, float size, int color, Paint p) {
        draw(c, name, x, y, size, color, STROKE, p);
    }

    // ---- SVG path data ----

    private static void parse(String d, Path out) {
        int[] pos = {0};
        char cmd = 0;
        float cx = 0, cy = 0, sx = 0, sy = 0, lx = 0, ly = 0;  // current point, subpath start, last control point
        char prev = 0;
        int n = d.length();
        while (true) {
            skip(d, pos);
            if (pos[0] >= n) break;
            char ch = d.charAt(pos[0]);
            if (Character.isLetter(ch)) {
                cmd = ch;
                pos[0]++;
                if (cmd == 'z' || cmd == 'Z') {
                    out.close();
                    cx = sx;
                    cy = sy;
                    prev = 'Z';
                    continue;
                }
            } else if (cmd == 'M') {
                cmd = 'L';
            } else if (cmd == 'm') {
                cmd = 'l';
            }
            boolean rel = Character.isLowerCase(cmd);
            char up = Character.toUpperCase(cmd);
            float ox = rel ? cx : 0, oy = rel ? cy : 0;
            switch (up) {
                case 'M': {
                    cx = ox + num(d, pos);
                    cy = oy + num(d, pos);
                    sx = cx;
                    sy = cy;
                    out.moveTo(cx, cy);
                    break;
                }
                case 'L':
                    cx = ox + num(d, pos);
                    cy = oy + num(d, pos);
                    out.lineTo(cx, cy);
                    break;
                case 'H':
                    cx = ox + num(d, pos);
                    out.lineTo(cx, cy);
                    break;
                case 'V':
                    cy = oy + num(d, pos);
                    out.lineTo(cx, cy);
                    break;
                case 'C': {
                    float x1 = ox + num(d, pos), y1 = oy + num(d, pos), x2 = ox + num(d, pos), y2 = oy + num(d, pos);
                    float x = ox + num(d, pos), y = oy + num(d, pos);
                    out.cubicTo(x1, y1, x2, y2, x, y);
                    lx = x2;
                    ly = y2;
                    cx = x;
                    cy = y;
                    break;
                }
                case 'S': {
                    float x1 = prev == 'C' || prev == 'S' ? 2 * cx - lx : cx, y1 = prev == 'C' || prev == 'S' ? 2 * cy - ly : cy;
                    float x2 = ox + num(d, pos), y2 = oy + num(d, pos), x = ox + num(d, pos), y = oy + num(d, pos);
                    out.cubicTo(x1, y1, x2, y2, x, y);
                    lx = x2;
                    ly = y2;
                    cx = x;
                    cy = y;
                    break;
                }
                case 'Q': {
                    float x1 = ox + num(d, pos), y1 = oy + num(d, pos), x = ox + num(d, pos), y = oy + num(d, pos);
                    out.quadTo(x1, y1, x, y);
                    lx = x1;
                    ly = y1;
                    cx = x;
                    cy = y;
                    break;
                }
                case 'T': {
                    float x1 = prev == 'Q' || prev == 'T' ? 2 * cx - lx : cx, y1 = prev == 'Q' || prev == 'T' ? 2 * cy - ly : cy;
                    float x = ox + num(d, pos), y = oy + num(d, pos);
                    out.quadTo(x1, y1, x, y);
                    lx = x1;
                    ly = y1;
                    cx = x;
                    cy = y;
                    break;
                }
                case 'A': {
                    float rx = num(d, pos), ry = num(d, pos), rot = num(d, pos);
                    boolean large = flag(d, pos), sweep = flag(d, pos);
                    float x = ox + num(d, pos), y = oy + num(d, pos);
                    arc(out, cx, cy, rx, ry, rot, large, sweep, x, y);
                    cx = x;
                    cy = y;
                    break;
                }
                default:
                    return;  // an unknown command: keep what was parsed
            }
            prev = up;
        }
    }

    private static void skip(String d, int[] pos) {
        while (pos[0] < d.length() && (d.charAt(pos[0]) == ' ' || d.charAt(pos[0]) == ',' || d.charAt(pos[0]) == '\n')) pos[0]++;
    }

    private static boolean flag(String d, int[] pos) {
        skip(d, pos);
        boolean v = pos[0] < d.length() && d.charAt(pos[0]) == '1';
        pos[0]++;
        return v;
    }

    private static float num(String d, int[] pos) {
        skip(d, pos);
        int i = pos[0], n = d.length(), start = i;
        if (i < n && (d.charAt(i) == '-' || d.charAt(i) == '+')) i++;
        boolean dot = false;
        while (i < n) {
            char ch = d.charAt(i);
            if (ch >= '0' && ch <= '9') i++;
            else if (ch == '.' && !dot) { dot = true; i++; }
            else break;
        }
        pos[0] = i;
        return i > start ? Float.parseFloat(d.substring(start, i)) : 0f;
    }

    /** SVG's endpoint arc (F.6.5) as up to four cubic segments per quarter turn. */
    private static void arc(Path out, float x1, float y1, float rxIn, float ryIn, float rotDeg, boolean large, boolean sweep,
                            float x2, float y2) {
        double rx = Math.abs(rxIn), ry = Math.abs(ryIn);
        if (rx == 0 || ry == 0 || (x1 == x2 && y1 == y2)) {
            out.lineTo(x2, y2);
            return;
        }
        double phi = Math.toRadians(rotDeg), cp = Math.cos(phi), sp = Math.sin(phi);
        double dx = (x1 - x2) / 2.0, dy = (y1 - y2) / 2.0;
        double x1p = cp * dx + sp * dy, y1p = -sp * dx + cp * dy;
        double lambda = x1p * x1p / (rx * rx) + y1p * y1p / (ry * ry);
        if (lambda > 1) {
            double s = Math.sqrt(lambda);
            rx *= s;
            ry *= s;
        }
        double num = rx * rx * ry * ry - rx * rx * y1p * y1p - ry * ry * x1p * x1p, den = rx * rx * y1p * y1p + ry * ry * x1p * x1p;
        double coef = (large == sweep ? -1 : 1) * Math.sqrt(Math.max(0, num / den));
        double cxp = coef * rx * y1p / ry, cyp = -coef * ry * x1p / rx;
        double cx = cp * cxp - sp * cyp + (x1 + x2) / 2.0, cy = sp * cxp + cp * cyp + (y1 + y2) / 2.0;
        double a1 = Math.atan2((y1p - cyp) / ry, (x1p - cxp) / rx);
        double a2 = Math.atan2((-y1p - cyp) / ry, (-x1p - cxp) / rx);
        double delta = a2 - a1;
        if (!sweep && delta > 0) delta -= 2 * Math.PI;
        if (sweep && delta < 0) delta += 2 * Math.PI;
        int segs = (int) Math.ceil(Math.abs(delta) / (Math.PI / 2) - 1e-9);
        double step = delta / Math.max(1, segs), t = 4.0 / 3.0 * Math.tan(step / 4);
        for (int i = 0; i < segs; ++i) {
            double a = a1 + i * step, b = a + step;
            double ca = Math.cos(a), sa = Math.sin(a), cb = Math.cos(b), sb = Math.sin(b);
            double[] u = {ca - t * sa, sa + t * ca, cb + t * sb, sb - t * cb, cb, sb};  // two controls and the end, on the unit circle
            float[] q = new float[6];
            for (int j = 0; j < 6; j += 2) {
                q[j] = (float) (cx + rx * u[j] * cp - ry * u[j + 1] * sp);
                q[j + 1] = (float) (cy + rx * u[j] * sp + ry * u[j + 1] * cp);
            }
            out.cubicTo(q[0], q[1], q[2], q[3], q[4], q[5]);
        }
    }
}
